import React, { useRef, useState, useMemo } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, Stars } from '@react-three/drei';
import * as THREE from 'three';

// 行星数据：名称、半径、距离、颜色、公转速度、自转速度
const planetData = [
  { name: '水星', radius: 0.38, distance: 2.8, color: '#A5A5A5', orbitSpeed: 4.15, rotSpeed: 0.004 },
  { name: '金星', radius: 0.95, distance: 4.0, color: '#E5C36B', orbitSpeed: 1.62, rotSpeed: 0.003 },
  { name: '地球', radius: 1.0, distance: 5.5, color: '#4B9CD3', orbitSpeed: 1.0, rotSpeed: 0.02 },
  { name: '火星', radius: 0.53, distance: 7.0, color: '#C16051', orbitSpeed: 0.53, rotSpeed: 0.019 },
  { name: '木星', radius: 2.8, distance: 10.0, color: '#C6842F', orbitSpeed: 0.18, rotSpeed: 0.04 },
  { name: '土星', radius: 2.4, distance: 14.0, color: '#E8C554', orbitSpeed: 0.12, rotSpeed: 0.045, hasRing: true },
  { name: '天王星', radius: 1.6, distance: 18.0, color: '#7B8BAA', orbitSpeed: 0.06, rotSpeed: 0.03 },
  { name: '海王星', radius: 1.5, distance: 21.0, color: '#3D58DB', orbitSpeed: 0.04, rotSpeed: 0.032 },
];

function Sun() {
  const meshRef = useRef();
  const lightRef = useRef();

  useFrame(() => {
    meshRef.current.rotation.y += 0.002;
  });

  return (
    <group>
      <mesh ref={meshRef} rotation={[0, 0, 0]}>
        <sphereGeometry args={[3, 64, 64]} />
        <meshStandardMaterial
          emissive={new THREE.Color('#FFD700')}
          emissiveIntensity={2}
          color={new THREE.Color('#FF6600')}
          toneMapped={false}
        />
      </mesh>
      <pointLight ref={lightRef} intensity={2} distance={50} />
    </group>
  );
}

function OrbitLine({ distance }) {
  const points = [];
  const segments = 128;
  for (let i = 0; i <= segments; i++) {
    const angle = (i / segments) * Math.PI * 2;
    points.push(new THREE.Vector3(Math.cos(angle) * distance, 0, Math.sin(angle) * distance));
  }
  const geometry = new THREE.BufferGeometry().setFromPoints(points);
  const material = new THREE.LineBasicMaterial({ color: 0x333333, transparent: true, opacity: 0.3 });
  return <line geometry={geometry} material={material} />;
}

function Planet({ data, index }) {
  const meshRef = useRef();
  const groupRef = useRef();
  const [hovered, setHovered] = useState(false);

  useFrame(() => {
    const time = Date.now() * 0.001;
    const angle = time * data.orbitSpeed;
    groupRef.current.position.x = Math.cos(angle) * data.distance;
    groupRef.current.position.z = Math.sin(angle) * data.distance;
    meshRef.current.rotation.y += data.rotSpeed;
  });

  return (
    <group ref={groupRef}>
      <mesh
        ref={meshRef}
        onPointerOver={() => setHovered(true)}
        onPointerOut={() => setHovered(false)}
      >
        <sphereGeometry args={[data.radius, 32, 32]} />
        <meshStandardMaterial
          color={data.color}
          emissive={hovered ? new THREE.Color(data.color).multiplyScalar(0.3) : new THREE.Color('#000000')}
          emissiveIntensity={hovered ? 0.5 : 0}
        />
      </mesh>
      {data.hasRing && (
        <mesh rotation={[0.4, 0, 0]}>
          <ringGeometry args={[data.radius * 1.4, data.radius * 2.2, 64]} />
          <meshStandardMaterial color="#C0A060" transparent opacity={0.7} side={THREE.DoubleSide} />
        </mesh>
      )}
      <mesh>
        <sphereGeometry args={[0.15, 16, 16]} />
        <meshBasicMaterial color="#FFFFFF" transparent opacity={0.8} />
      </mesh>
      <primitive position={[0, 0, 0]} />
    </group>
  );
}

function App() {
  return (
    <div style={{ width: '100vw', height: '100vh' }}>
      <Canvas camera={{ position: [0, 20, 30], fov: 50 }}>
        <color attach="background" args={['#050510']} />
        <ambientLight intensity={0.1} />
        <OrbitControls makeDefault />
        <Starfield count={5000} radius={100} opacity={0.5} />
        <Sun />
        {planetData.map((planet, index) => (
          <React.Fragment key={index}>
            <OrbitLine distance={planet.distance} />
            <Planet data={planet} index={index} />
          </React.Fragment>
        ))}
      </Canvas>
      <div style={{
        position: 'fixed',
        top: '10px',
        left: '10px',
        color: '#FFFFFF',
        fontFamily: 'monospace',
        fontSize: '14px',
        zIndex: 1000,
        pointerEvents: 'none',
        background: 'rgba(0,0,0,0.5)',
        padding: '10px',
        borderRadius: '5px'
      }}>
        <div>太阳系模拟</div>
        <div style={{ fontSize: '12px', marginTop: '5px', opacity: 0.7 }}>
          鼠标左键旋转 · 右键平移 · 滚轮缩放
        </div>
      </div>
    </div>
  );
}

export default App;
